-- Native integration events, emitted inside the same business transaction.

CREATE FUNCTION event_cost_centers() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.company_id,(NEW.id)::text,NEW.version,'created',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'cost-centers'); ELSE INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.company_id,(NEW.id)::text,NEW.version,'updated',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'cost-centers'); END IF; RETURN NULL; END $$;

CREATE TRIGGER event_cost_centers AFTER INSERT OR UPDATE ON cost_centers FOR EACH ROW EXECUTE FUNCTION event_cost_centers();

CREATE FUNCTION event_company() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN IF 1=1 THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.id,(NEW.id)::text,NEW.version,'created',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'company'); END IF; ELSIF TG_OP='DELETE' THEN IF 1=1 THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),OLD.id,(OLD.id)::text,OLD.version,'deleted',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'company'); END IF; ELSE IF (1=1) AND (1=1) AND (NEW.id=OLD.id AND NEW.id=OLD.id) THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.id,(NEW.id)::text,NEW.version,'updated',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'company'); END IF; IF (1=1) AND (NOT (1=1) OR NOT (NEW.id=OLD.id AND NEW.id=OLD.id)) THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),OLD.id,(OLD.id)::text,OLD.version,'deleted',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'company'); END IF; IF (1=1) AND (NOT (1=1) OR NOT (NEW.id=OLD.id AND NEW.id=OLD.id)) THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.id,(NEW.id)::text,NEW.version,'created',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'company'); END IF; END IF; RETURN NULL; END $$;

CREATE TRIGGER event_company AFTER INSERT OR UPDATE OR DELETE ON companies FOR EACH ROW EXECUTE FUNCTION event_company();

