id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.company_id,(NEW.module || ':' || NEW.year)::text,0,'created',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'financial-exercises'); END IF; END IF; RETURN NULL; END $$;

CREATE TRIGGER event_financial_exercises AFTER INSERT OR UPDATE OR DELETE ON exercises FOR EACH ROW EXECUTE FUNCTION event_financial_exercises();

