ion_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.company_id,(NEW.module || ':' || NEW.period)::text,NEW.version,'created',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'social-periods'); END IF; END IF; RETURN NULL; END $$;

