CREATE FUNCTION event_accounting_imports() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.module='accounting' THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.company_id,(NEW.id)::text,0,'created',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'accounting-imports'); END IF; ELSIF TG_OP='DELETE' THEN IF OLD.module='accounting' THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),OLD.company_id,(OLD.id)::text,0,'deleted',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'accounting-imports'); END IF; ELSE IF (NEW.module='accounting') AND (OLD.module='accounting') AND (NEW.company_id=OLD.company_id AND NEW.id=OLD.id) THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.company_id,(NEW.id)::text,0,'updated',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'accounting-imports'); END IF; IF (OLD.module='accounting') AND (NOT (NEW.module='accounting') OR NOT (NEW.company_id=OLD.company_id AND NEW.id=OLD.id)) THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),OLD.company_id,(OLD.id)::text,0,'deleted',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'accounting-imports'); END IF; IF (NEW.module='accounting') AND (NOT (OLD.module='accounting') OR NOT (NEW.company_id=OLD.company_id AND NEW.id=OLD.id)) THEN INSERT INTO integration_events(id,company_id,resource_id,version,operation,created,resource) VALUES(replace(gen_random_uuid()::text,'-',''),NEW.company_id,(NEW.id)::text,0,'created',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'accounting-imports'); END IF; END IF; RETURN NULL; END $$;

CREATE TRIGGER event_accounting_imports AFTER INSERT OR UPDATE OR DELETE ON module_imports FOR EACH ROW EXECUTE FUNCTION event_accounting_imports();

